+<script>
+  function filterRows(tag, btn) {
+    document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active','active-bug','active-perf','active-feat','active-doc','active-jax','active-refactor'));
+    if (tag === 'all') {
+      btn.classList.add('active');
+    } else {
+      btn.classList.add('active-' + (tag === 'refactor' ? 'refactor' : tag === 'high' ? 'bug' : tag));
+    }
+
+    let visible = 0;
+    document.querySelectorAll('#issues-table tbody tr').forEach(row => {
+      const tags = row.dataset.tags || '';
+      let show = false;
+      if (tag === 'all') show = true;
+      else if (tag === 'high') show = tags.includes('high');
+      else show = tags.includes(tag);
+      row.classList.toggle('hidden', !show);
+      if (show) visible++;
+    });
+
+    document.getElementById('total-count').textContent = visible;
+    document.getElementById('no-results').style.display = visible === 0 ? 'block' : 'none';
+  }
+</script>
